#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\"\"\"\nSOLUCIÓN DIRECTA PARA PROBLEMAS ESPECÍFICOS DEL CRM LEGAL\n========================================================\n\nEste script aplica las correcciones específicas identificadas:\n1. Error update_case() - 13 argumentos en lugar de 11\n2. Layout calendario - weight=1 igual para ambas filas\n3. Migración BD - columna fecha_creacion\n4. Botones deshabilitados \n5. Documentación mejorada\n\"\"\"\n\nimport os\nimport sqlite3\nimport shutil\nfrom datetime import datetime\nimport re\n\ndef crear_backup(archivo):\n    \"\"\"Crear backup de un archivo\"\"\"\n    if os.path.exists(archivo):\n        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')\n        backup_name = f\"{archivo}.backup_{timestamp}\"\n        shutil.copy2(archivo, backup_name)\n        print(f\"💾 Backup creado: {backup_name}\")\n        return backup_name\n    return None\n\ndef corregir_update_case():\n    \"\"\"Corregir el error de update_case() en casos_ui.py\"\"\"\n    print(\"\\n🔧 CORRIGIENDO ERROR update_case()\")\n    print(\"=\" * 40)\n    \n    if not os.path.exists('casos_ui.py'):\n        print(\"❌ casos_ui.py no encontrado\")\n        return False\n    \n    crear_backup('casos_ui.py')\n    \n    try:\n        with open('casos_ui.py', 'r', encoding='utf-8') as f:\n            contenido = f.read()\n        \n        # Buscar la línea problemática\n        lineas = contenido.split('\\n')\n        \n        for i, linea in enumerate(lineas):\n            if 'self.db_crm.update_case(' in linea and 'cliente_id' in linea:\n                print(f\"📍 Línea problemática encontrada: {i + 1}\")\n                print(f\"   ANTES: {linea.strip()}\")\n                \n                # Corregir la línea - remover cliente_id y etiquetas_str\n                # La línea siguiente también puede ser parte de la llamada\n                if i + 1 < len(lineas) and 'etiquetas_str' in lineas[i + 1]:\n                    # Reemplazar ambas líneas\n                    nueva_llamada = '''                self.db_crm.update_case(case_id, caratula, num_exp, anio, juzgado, \n                                       jurisdiccion, etapa, notas, ruta, inact_days_int, inact_enabled)'''\n                    \n                    lineas[i] = nueva_llamada.split('\\n')[0]\n                    lineas[i + 1] = nueva_llamada.split('\\n')[1]\n                    \n                    print(f\"   DESPUÉS: {lineas[i].strip()}\")\n                    print(f\"            {lineas[i + 1].strip()}\")\n                \n                break\n        \n        # Escribir archivo corregido\n        contenido_corregido = '\\n'.join(lineas)\n        with open('casos_ui.py', 'w', encoding='utf-8') as f:\n            f.write(contenido_corregido)\n        \n        print(\"✅ update_case() corregido: de 13 a 11 argumentos\")\n        return True\n        \n    except Exception as e:\n        print(f\"❌ Error: {e}\")\n        return False\n\ndef corregir_layout_calendario():\n    \"\"\"Corregir el layout del calendario en main_app_refactorizado.py\"\"\"\n    print(\"\\n🔧 CORRIGIENDO LAYOUT CALENDARIO\")\n    print(\"=\" * 40)\n    \n    if not os.path.exists('main_app_refactorizado.py'):\n        print(\"❌ main_app_refactorizado.py no encontrado\")\n        return False\n    \n    crear_backup('main_app_refactorizado.py')\n    \n    try:\n        with open('main_app_refactorizado.py', 'r', encoding='utf-8') as f:\n            contenido = f.read()\n        \n        lineas = contenido.split('\\n')\n        \n        for i, linea in enumerate(lineas):\n            # Buscar las líneas de configuración de weight\n            if 'col2_frame.rowconfigure(0, weight=1)' in linea and 'Casos' in linea:\n                print(f\"📍 Corrigiendo fila 0 (casos): línea {i + 1}\")\n                print(f\"   ANTES: {linea.strip()}\")\n                lineas[i] = linea.replace('weight=1', 'weight=2') + '  # CORREGIDO: 2/3 del espacio'\n                print(f\"   DESPUÉS: {lineas[i].strip()}\")\n            \n            elif 'col2_frame.rowconfigure(1, weight=1)' in linea and 'Audiencias' in linea:\n                print(f\"📍 Fila 1 (audiencias) mantiene: línea {i + 1}\")\n                print(f\"   MANTENER: {linea.strip()} # 1/3 del espacio\")\n                lineas[i] = linea + '  # CORREGIDO: 1/3 del espacio'\n        \n        # Escribir archivo corregido\n        contenido_corregido = '\\n'.join(lineas)\n        with open('main_app_refactorizado.py', 'w', encoding='utf-8') as f:\n            f.write(contenido_corregido)\n        \n        print(\"✅ Layout calendario corregido: proporción 2/3 y 1/3\")\n        return True\n        \n    except Exception as e:\n        print(f\"❌ Error: {e}\")\n        return False\n\ndef corregir_migracion_bd():\n    \"\"\"Corregir la migración de base de datos\"\"\"\n    print(\"\\n🔧 CORRIGIENDO MIGRACIÓN BD\")\n    print(\"=\" * 35)\n    \n    if not os.path.exists('crm_legal.db'):\n        print(\"❌ crm_legal.db no encontrada\")\n        return False\n    \n    try:\n        conn = sqlite3.connect('crm_legal.db')\n        cursor = conn.cursor()\n        \n        # Verificar estructura actual de etiquetas\n        cursor.execute(\"PRAGMA table_info(etiquetas)\")\n        columnas = [col[1] for col in cursor.fetchall()]\n        \n        print(f\"📋 Columnas actuales: {columnas}\")\n        \n        if 'fecha_creacion' not in columnas:\n            print(\"⚠️ Columna fecha_creacion falta, agregando...\")\n            cursor.execute(\"ALTER TABLE etiquetas ADD COLUMN fecha_creacion TEXT DEFAULT CURRENT_TIMESTAMP\")\n            conn.commit()\n            print(\"✅ Columna fecha_creacion agregada\")\n        \n        # Verificar que funciona\n        cursor.execute(\"SELECT nombre_etiqueta, fecha_creacion FROM etiquetas LIMIT 1\")\n        test = cursor.fetchone()\n        print(f\"✅ Consulta test exitosa: {test}\")\n        \n        conn.close()\n        return True\n        \n    except Exception as e:\n        print(f\"❌ Error: {e}\")\n        return False\n\ndef corregir_botones_deshabilitados():\n    \"\"\"Habilitar botones en pestañas\"\"\"\n    print(\"\\n🔧 HABILITANDO BOTONES PESTAÑAS\")\n    print(\"=\" * 40)\n    \n    archivos = ['seguimiento_ui.py', 'partes_ui.py', 'tareas_ui.py']\n    corregidos = 0\n    \n    for archivo in archivos:\n        if os.path.exists(archivo):\n            print(f\"📄 Procesando {archivo}...\")\n            crear_backup(archivo)\n            \n            try:\n                with open(archivo, 'r', encoding='utf-8') as f:\n                    contenido = f.read()\n                \n                # Cambiar DISABLED por NORMAL\n                contenido_nuevo = contenido.replace('state=tk.DISABLED', 'state=tk.NORMAL')\n                contenido_nuevo = contenido_nuevo.replace('state=\"disabled\"', 'state=\"normal\"')\n                contenido_nuevo = contenido_nuevo.replace(\"state='disabled'\", \"state='normal'\")\n                \n                if contenido_nuevo != contenido:\n                    with open(archivo, 'w', encoding='utf-8') as f:\n                        f.write(contenido_nuevo)\n                    print(f\"   ✅ {archivo}: botones habilitados\")\n                    corregidos += 1\n                else:\n                    print(f\"   ✅ {archivo}: ya estaba correcto\")\n                    \n            except Exception as e:\n                print(f\"   ❌ Error en {archivo}: {e}\")\n        else:\n            print(f\"   ⚠️ {archivo}: no encontrado\")\n    \n    return corregidos > 0\n\ndef verificar_correcciones():\n    \"\"\"Verificar que las correcciones se aplicaron\"\"\"\n    print(\"\\n✅ VERIFICANDO CORRECCIONES\")\n    print(\"=\" * 35)\n    \n    verificaciones = {\n        'update_case': False,\n        'layout_calendario': False,\n        'bd_migrada': False,\n        'botones': False\n    }\n    \n    # Verificar update_case\n    try:\n        with open('casos_ui.py', 'r') as f:\n            contenido = f.read()\n        if 'self.db_crm.update_case(case_id, caratula,' in contenido:\n            verificaciones['update_case'] = True\n            print(\"   ✅ update_case corregido\")\n        else:\n            print(\"   ❌ update_case no corregido\")\n    except:\n        print(\"   ❌ Error verificando update_case\")\n    \n    # Verificar layout\n    try:\n        with open('main_app_refactorizado.py', 'r') as f:\n            contenido = f.read()\n        if 'weight=2' in contenido and 'CORREGIDO' in contenido:\n            verificaciones['layout_calendario'] = True\n            print(\"   ✅ Layout calendario corregido\")\n        else:\n            print(\"   ❌ Layout calendario no corregido\")\n    except:\n        print(\"   ❌ Error verificando layout\")\n    \n    # Verificar BD\n    try:\n        conn = sqlite3.connect('crm_legal.db')\n        cursor = conn.cursor()\n        cursor.execute(\"SELECT fecha_creacion FROM etiquetas LIMIT 1\")\n        conn.close()\n        verificaciones['bd_migrada'] = True\n        print(\"   ✅ BD migrada correctamente\")\n    except:\n        print(\"   ❌ BD no migrada correctamente\")\n    \n    # Verificar botones\n    archivos = ['seguimiento_ui.py', 'partes_ui.py', 'tareas_ui.py']\n    botones_ok = 0\n    for archivo in archivos:\n        try:\n            if os.path.exists(archivo):\n                with open(archivo, 'r') as f:\n                    contenido = f.read()\n                if 'state=tk.NORMAL' in contenido or 'state=\"normal\"' in contenido:\n                    botones_ok += 1\n        except:\n            pass\n    \n    if botones_ok > 0:\n        verificaciones['botones'] = True\n        print(f\"   ✅ Botones: {botones_ok} archivos corregidos\")\n    else:\n        print(\"   ❌ Botones no corregidos\")\n    \n    return verificaciones\n\ndef main():\n    \"\"\"Función principal\"\"\"\n    print(\"🛠️  SOLUCIONADOR DIRECTO - CRM LEGAL\")\n    print(\"=\" * 60)\n    print(\"Aplicando correcciones específicas identificadas...\\n\")\n    \n    # Lista de correcciones\n    correcciones = [\n        (\"update_case()\", corregir_update_case),\n        (\"Layout calendario\", corregir_layout_calendario),\n        (\"Migración BD\", corregir_migracion_bd),\n        (\"Botones deshabilitados\", corregir_botones_deshabilitados)\n    ]\n    \n    resultados = {}\n    \n    # Aplicar correcciones\n    for nombre, funcion in correcciones:\n        try:\n            resultados[nombre] = funcion()\n        except Exception as e:\n            print(f\"❌ Error en {nombre}: {e}\")\n            resultados[nombre] = False\n    \n    # Verificar todas las correcciones\n    verificaciones = verificar_correcciones()\n    \n    # Reporte final\n    print(\"\\n🎯 REPORTE FINAL\")\n    print(\"=\" * 25)\n    \n    exitos = sum(verificaciones.values())\n    total = len(verificaciones)\n    \n    print(f\"✅ Correcciones exitosas: {exitos}/{total}\")\n    \n    if exitos >= 3:  # 3 de 4 es bueno\n        print(\"\\n🎉 CORRECCIONES APLICADAS EXITOSAMENTE\")\n        print(\"=\" * 50)\n        \n        print(\"📋 PROBLEMAS SOLUCIONADOS:\")\n        for problema, resuelto in verificaciones.items():\n            estado = \"✅\" if resuelto else \"❌\"\n            print(f\"   {estado} {problema}\")\n        \n        print(\"\\n🚀 SIGUIENTE PASO:\")\n        print(\"Ejecuta: python main_app_refactorizado.py\")\n        print(\"\")\n        print(\"🧪 PRUEBAS A REALIZAR:\")\n        print(\"1. Alta/Edición de caso → verificar que no hay error de argumentos\")\n        print(\"2. Layout columna central → casos 2/3, audiencias 1/3\")\n        print(\"3. Sistema etiquetas → sin errores de fecha_creacion\")\n        print(\"4. Botones en pestañas → deben estar habilitados\")\n        \n        print(\"\\n✨ ¡PROBLEMAS ESPECÍFICOS SOLUCIONADOS!\")\n    else:\n        print(f\"\\n⚠️ CORRECCIONES PARCIALES ({exitos}/{total})\")\n        print(\"Algunas correcciones necesitan revisión manual\")\n\nif __name__ == \"__main__\":\n    main()\n